/* Account-level workspace switcher and complete local Team prototype. */
(() => {
  'use strict';
  const M=window.WorkspaceModel;if(!M)return;
  let data=M.load(localStorage), page='overview', filter='all', query='', actor=M.SELF, selected=null, tab='summary', editing=false, noteDraft='', draft='', agentOpen=false;
  let setup={step:0,name:'',country:'中国',cycle:'year',seats:3,orderId:M.id('order')}, answer='', menuAnchor=null;
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=v=>'¥'+Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
  const creditNumber=v=>Number(v).toLocaleString('zh-CN',{maximumFractionDigits:3});
  const date=v=>String(v||'').replace('T',' ').slice(0,16);
  const w=()=>M.get(data), isAdmin=()=>M.admin(w(),actor), userName=uid=>w().members.find(m=>m.id===uid)?.name||'已移除成员';
  const memberCount=space=>space.members.filter(m=>m.status==='active').length;
  const icon=name=>`<svg class="ws-icon" aria-hidden="true"><use href="#ico-${name}"/></svg>`;
  const btn=(action,label,cls='',value='',extra='')=>`<button type="button" class="ws-btn ${cls}" data-ws-action="${action}" data-value="${esc(value)}" ${extra}>${label}</button>`;
  const badge=(text,kind='')=>`<span class="ws-badge ${kind}">${esc(text)}</span>`;
  const empty=(title,text,action='')=>`<div class="ws-empty">${icon('folder')}<h3>${title}</h3><p>${text}</p>${action}</div>`;
  let activeHistoryId=null,activeInsightId=null,historyTab='all';
  let agentOptions={mode:'quick',web:false,appData:false,fileIds:[]};
  const resetAgentOptions=()=>{agentOptions={mode:'quick',web:false,appData:false,fileIds:[]};};
  let sourceFilter='all',dateFilter='',statusFilter='all',listPage=1,sortKey='created',sortAsc=false,recordingContext=null;
  let savedState=localStorage.getItem(M.KEY), deviceRegistration=null;
  const save=()=>{try{const next=JSON.stringify(data);localStorage.setItem(M.KEY,next);savedState=next;}catch{throw new Error('浏览器存储空间不足，请导出重要资料后重试');}};
  const toast=message=>{const n=$('#ws-toast');n.textContent=message;n.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.hidden=true,3800);};
  const mutate=fn=>{const backup=M.clone(data);try{const result=fn();save();return result;}catch(e){data=backup;throw e;}};
  const field=(label,name,value='',type='text',extra='')=>`<label class="ws-field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
  const select=(label,name,options,value)=>`<label class="ws-field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
  const root=document.createElement('section');root.id='ws-view';root.className='ws-view';root.dataset.mainView='workspaces';root.hidden=true;$('.main').append(root);
  const dialog=document.createElement('dialog');dialog.id='ws-dialog';dialog.className='ws-dialog';document.body.append(dialog);
  const menu=document.createElement('div');menu.id='ws-menu';menu.className='ws-menu';menu.hidden=true;menu.setAttribute('role','dialog');menu.setAttribute('aria-label','切换工作空间');document.body.append(menu);
  const notice=document.createElement('div');notice.id='ws-toast';notice.className='ws-toast';notice.setAttribute('role','status');notice.hidden=true;document.body.append(notice);
  const switcher=document.createElement('button');switcher.type='button';switcher.id='ws-switcher';switcher.className='ws-switcher';switcher.dataset.wsAction='menu';switcher.setAttribute('aria-controls','ws-menu');switcher.setAttribute('aria-expanded','false');$('.brand-row').after(switcher);
  const nav=document.createElement('nav');nav.id='ws-team-nav';nav.className='ws-team-nav';nav.setAttribute('aria-label','团队工作空间');$('.sidebar-quick-nav').after(nav);
  // Reference the existing personal meeting store without copying it into any Team.
  function refreshPersonal(){
    const personal=M.get(data,'personal');
    const records=window.MeetingDetail?.snapshot?.()||[];
    personal.files=personal.files.filter(f=>!f.nativeId&&!/^personal-\d+$/.test(f.id)).concat(records.map(r=>({...r,id:'native-'+r.id,nativeId:r.id,owner:M.SELF,shared:[],duration:30,deleted:false})));
  }
  refreshPersonal();
  function chrome(){
    document.body.dataset.wsType=w().type;
    document.title=`EurekaMind · ${w().name}`;
    $('[data-contacts-entry]')?.toggleAttribute('hidden',w().type==='team');
    const contactCount=$('[data-contacts-entry] .tree-count');if(contactCount)contactCount.textContent=w().type==='team'?String((w().contacts||[]).length):String(window.ContactsModel?.load('personal','personal').data.contacts.length||6);
    switcher.innerHTML=`<span class="ws-space-avatar">${w().type==='personal'?icon('user'):icon('users')}</span><span class="ws-space-copy"><strong>${esc(w().name)}</strong><small>${w().type==='personal'?'Personal · '+esc(PS.current(w()).plan):'Team · '+(isAdmin()?'管理员':'成员')+' · '+memberCount(w())+' 位成员'}</small></span>${icon('chevron')}`;
    switcher.title=`切换工作空间：${w().name}`;
    nav.innerHTML=w().type==='team'?`<div class="ws-nav-label">工作空间</div>${btn('page',icon('users')+'团队成员',page==='members'?'active':'','members')}${btn('page',icon('phone')+'设备',page==='devices'?'active':'','devices')}${isAdmin()?btn('page',icon('task')+'空间管理',['billing','settings','credits','audit'].includes(page)?'active':'','billing'):''}`:'';
    let history=$('#ws-history');if(!history){history=document.createElement('div');history.id='ws-history';nav.after(history);}
    const threads=M.history(w(),actor), parents=new Set(threads.map(t=>t.parentThreadId).filter(Boolean));
    const rows=threads.filter(t=>!parents.has(t.id)).map(t=>({id:t.id,title:t.title||t.prompt,time:date(t.time).slice(5),type:'history'}));
    const tasks=M.scheduledTasks(w(),actor).map(t=>({id:t.id,title:t.title,time:t.enabled?t.time:'已暂停',type:'auto-task'}));
    history.innerHTML=w().type==='team'?`<div class="ws-nav-label">历史会话</div><div class="history-tabs" role="tablist" aria-label="团队任务分类">${[['all','全部任务'],['scheduled','自动任务']].map(([id,label])=>btn('history-tab',label,'history-tab '+(historyTab===id?'active':''),id,`role="tab" aria-selected="${historyTab===id}" aria-controls="ws-task-list"`)).join('')}</div><div id="ws-task-list" role="tabpanel" aria-label="${historyTab==='all'?'全部任务':'自动任务'}">${(historyTab==='all'?[...rows,...tasks]:tasks).map(t=>`<div class="ws-history-row">${btn(t.type,`${icon(t.type==='history'?'chat':'clock')}<span class="ws-history-title">${esc(t.title)}</span><time>${esc(t.time)}</time>`,activeHistoryId===t.id&&agentOpen?'active':'',t.id,`title="${esc(t.title)}" ${activeHistoryId===t.id&&agentOpen?'aria-current="true"':''}`)}${btn(t.type==='history'?'history-delete':'auto-delete',icon('trash'),'ws-history-delete',t.id,`aria-label="删除${t.type==='history'?'会话':'自动任务'}：${esc(t.title)}"`)}</div>`).join('')||'<p class="ws-muted">暂无会话或自动任务</p>'}</div>${historyTab==='scheduled'?btn('auto-new',icon('plus')+'新建自动任务','ws-auto-new'):''}`:'';
    const name=$('#user-card .user-name');if(name)name.textContent=data.account.name+"‘s Space";
  }
  function closeMenu(){menu.hidden=true;switcher.setAttribute('aria-expanded','false');$('#user-card')?.setAttribute('aria-expanded','false');}
  function openMenu(anchor){
    if(!menu.hidden&&menuAnchor===anchor){closeMenu();return;}closeMenu();menuAnchor=anchor;const accountMenu=anchor.id==='user-card';menu.setAttribute('aria-label',accountMenu?'我的账户与工作空间':'切换工作空间');menu.dataset.mode=accountMenu?'account':'spaces';$('#user-menu')?.classList.remove('show');
    menu.innerHTML=`<div class="ws-menu-head"><span class="ws-space-avatar">${icon(w().type==='team'?'users':'user')}</span><div><strong>${esc(w().name)}</strong><small>${esc(data.account.email)}</small></div></div><div class="ws-menu-caption">工作空间</div>${data.spaces.filter(s=>M.member(s)).map(s=>btn('switch',`<span class="ws-mini-avatar">${s.type==='personal'?'P':esc(s.name[0])}</span><span>${esc(s.name)}<small>${s.type==='personal'?'个人订阅独立计费':(M.admin(s)?'管理员':'成员')+' · '+memberCount(s)+' 位成员 · Team Unlimited'}</small></span><b>${s.id===data.activeId?'✓':''}</b>`,'ws-menu-space',s.id)).join('')}<div class="ws-menu-divider"></div>${btn('plan',icon('plus')+'创建团队工作空间','ws-menu-item')}${btn('invites',icon('users')+`工作空间邀请 ${badge(data.invitations.filter(i=>i.status==='pending').length)}`,'ws-menu-item')}${w().type==='team'&&isAdmin()?btn('invite',icon('users')+'邀请空间成员','ws-menu-item'):''}${accountMenu?`<div class="ws-menu-divider"></div>${btn('page',icon('mic')+'会议录音','ws-menu-item','files')}${btn('page',icon('phone')+'设备与同步','ws-menu-item','devices')}${btn('page',icon('task')+(w().type==='personal'?'个人订阅':'订阅与席位'),'ws-menu-item','billing')}${btn('settings',icon('edit')+'设置','ws-menu-item')}${btn('logout',icon('collapse')+'退出登录','ws-menu-item')}`:''}<p class="ws-menu-note">同一账号 · 各空间的数据与订阅独立</p>`;
    menu.hidden=false;anchor.setAttribute('aria-expanded','true');const rect=anchor.getBoundingClientRect();menu.style.left=Math.min(Math.max(12,rect.left),innerWidth-Math.min(338,innerWidth-24)-12)+'px';menu.style.top='';menu.style.bottom='';if(rect.top>innerHeight/2)menu.style.bottom=(innerHeight-rect.top+8)+'px';else menu.style.top=Math.min(rect.bottom+8,innerHeight-200)+'px';
  }
  function switchSpace(uid){
    if(editing){confirm('退出编辑？','未保存的内容会丢失。',()=>{editing=false;switchSpace(uid);});return;}
    if(recordingContext&&!window.RecordingUI?.ended()){confirm('结束当前录音并切换？','尚未保存的演示录音会被放弃。',()=>{window.RecordingUI?.stop();recordingContext=null;switchSpace(uid);});return;}
    window.MeetingDetail?.leaveWorkspace();window.ContactsUI?.leaveWorkspace();
    M.get(data,uid);mutate(()=>data.activeId=uid);actor=M.SELF;historyTab='all';resetAgentOptions();query='';sourceFilter='all';dateFilter='';statusFilter='all';listPage=1;selected=null;filter='all';answer='';draft='';agentOpen=false;activeHistoryId=null;activeInsightId=null;closeMenu();chrome();
    if(w().type==='personal'){root.hidden=true;showMainView('home',{silent:true});}else show('overview');
    toast(`已切换至${w().name}`);
  }
  function show(next='overview'){
    if(editing&&next!==page){confirm('退出编辑？','未保存的内容会丢失。',()=>{editing=false;show(next);});return;}
    if(next==='contacts'&&w().type==='team')next='overview';
    if(next==='files'&&w().type==='team')next='overview';
    closeMenu();page=next;for(const entry of $$('#home-entry,#start-recording,[data-contacts-entry]')){const active=entry.id==='home-entry'&&next==='overview';entry.classList.toggle('active',active);if(active)entry.setAttribute('aria-current','page');else entry.removeAttribute('aria-current');}if(next!=='detail')selected=null;document.dispatchEvent(new Event('meeting-agent-leave'));$$('[data-main-view]').forEach(el=>{el.hidden=el!==root;el.setAttribute('aria-hidden',String(el!==root));});$('#page-crumb').textContent=w().type==='team'?w().name:'个人工作空间';$('.main').scrollTop=0;root.hidden=false;chrome();render();fit();
  }
  function fit(){if(root.hidden)return;root.style.setProperty('--ws-top',`${root.getBoundingClientRect().top+$('.main').scrollTop}px`);}
  const heading=(title,subtitle,actions='')=>`<header class="ws-page-head"><div><div class="ws-eyebrow">${esc(w().name)} ${w().type==='team'?badge(isAdmin()?'管理员':'成员'):badge('Personal')}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="ws-actions">${actions}</div></header>`;
  const managementTabs=()=>`<nav class="ws-tabs" aria-label="空间管理">${[['billing','订阅与席位'],['credits','Credits'],['settings','通用设置'],['audit','活动记录']].map(([k,v])=>btn('page',v,page===k?'active':'',k)).join('')}</nav>`;
  const filesRows=files=>files.map(f=>`<tr><td><button class="ws-file-link" data-ws-action="file" data-value="${esc(f.id)}">${icon('file')}<span><strong>${esc(f.title)}</strong><small>${esc(f.source)} · ${f.duration} 分钟</small></span></button></td><td>${esc(userName(f.owner))}${f.owner===actor?'（我）':''}</td><td>${badge(f.shared.length?'已分享':'仅自己',f.shared.length?'blue':'')}</td><td>${date(f.created)}</td><td>${btn('export',icon('download'),'ws-icon-button',f.id,'aria-label="导出 '+esc(f.title)+'"')}</td></tr>`).join('');
  const fileTable=files=>`<div class="ws-table-scroll"><table class="ws-table"><thead><tr><th>文件名</th><th>所有者</th><th>可见范围</th><th>录音时间</th><th>导出</th></tr></thead><tbody>${filesRows(files)}</tbody></table></div>`;
  function recordingList() {
    let list=filter==='trash'?w().files.filter(f=>f.owner===actor&&f.deleted&&(!f.deletedAt||Date.now()-new Date(f.deletedAt).getTime()<30*86400000)):M.visible(w(),actor);
    list=list.filter(f=>f.title.toLowerCase().includes(query.toLowerCase())&&(sourceFilter==='all'||f.source===sourceFilter)&&(!dateFilter||f.created.slice(0,10)===dateFilter)&&(statusFilter==='all'||(f.status||'已总结')===statusFilter));
    list.sort((a,b)=>String(a[sortKey]||'').localeCompare(String(b[sortKey]||''),'zh-CN')*(sortAsc?1:-1));
    return list;
  }
  function meetingTable(){
    const list=recordingList(),pages=Math.max(1,Math.ceil(list.length/10));listPage=Math.min(listPage,pages);
    const columns=filter==='trash'?['文件名','文件大小','文件来源','录音时间','删除时间','操作']:['文件名','文件大小','创建人','文件来源','标签','录音时长','文件状态','录音时间','更新时间','操作'];
    return `<div class="ws-table-scroll ws-recording-scroll" role="region" aria-label="团队会议录音列表" tabindex="0"><table class="ws-table ws-recording-table"><thead><tr>${columns.map(t=>`<th>${['录音时间','更新时间'].includes(t)?btn('sort',t+(sortKey===(t==='录音时间'?'created':'updated')?(sortAsc?' ↑':' ↓'):''),'link',t==='录音时间'?'created':'updated'):t}</th>`).join('')}</tr></thead><tbody>${list.slice((listPage-1)*10,listPage*10).map(f=>`<tr><td>${filter==='trash'?esc(f.title):`<button class="ws-file-link" data-ws-action="file" data-value="${esc(f.id)}">${icon('mic')}<strong>${esc(f.title)}</strong></button>`}</td><td>${esc(f.size||'—')}</td>${filter==='trash'?`<td>${esc(f.source)}</td><td>${date(f.created)}</td><td>${date(f.deletedAt)}</td><td><div class="ws-actions">${btn('restore','恢复','link',f.id)}${btn('purge','永久删除','link danger',f.id)}</div></td>`:`<td>${esc(f.creator||userName(f.owner))}</td><td>${esc(f.source)}</td><td>${(f.tags||[]).map(t=>badge(t)).join(' ')}</td><td>${f.origin==='upload'&&!f.duration?'待识别':f.duration+' 分钟'}</td><td>${badge(f.status||'已总结',(!f.status||f.status==='已总结')?'green':'amber')}</td><td>${date(f.created)}</td><td>${date(f.updated||f.created)}</td><td><div class="ws-actions">${f.owner===actor?btn('delete','删除','link danger',f.id):badge('只读')}</div></td>`}</tr>`).join('')}</tbody></table></div>${!list.length?empty(filter==='trash'?'回收站暂无内容':'没有符合条件的会议','调整筛选，或开始一场新的录音。'):''}<div class="ws-table-foot ws-pagination"><span>共 ${list.length} 个会议笔记 · ${listPage} / ${pages} 页</span><div class="ws-actions">${btn('list-prev','上一页','','',listPage<=1?'disabled':'')}${btn('list-next','下一页','','',listPage>=pages?'disabled':'')}</div></div>`;
  }
  function teamIntelligence(report){
    const items=report.items;
    return `<section class="ws-meeting-intelligence ws-surface ws-team-intelligence ws-team-brief" aria-label="团队简报"><header class="ws-intelligence-top"><div class="ws-intelligence-label">${icon('spark')} Agent 团队简报 <span>本地模拟</span></div><span class="ws-insight-scope">基于你可访问的会议</span></header>${items.length?`<div class="ws-brief-narrative">${items.map(i=>`<article class="ws-brief-finding" data-insight-id="${esc(i.id)}"><p class="ws-brief-paragraph"><strong>${esc(i.title)}。</strong>${esc(i.description)} <span class="ws-brief-attribution"><span>${esc([...new Set(i.sources.map(e=>userName(e.owner)))].join('、'))}的 ${i.sources.length} 场会议</span>${btn('meeting-prompt',icon('spark')+'问问 Agent','ws-brief-ask',i.title,'aria-label="问问 Agent：'+esc(i.title)+'"')}</span></p></article>`).join('')}</div>`:`<div class="ws-insight-empty">暂时没有形成新的跨会议发现。相关讨论积累后，Agent 会在这里串联值得团队关注的信息。</div>`}</section>`;
  }
  function overview(){
    const report=M.insights(w(),actor),now=new Date(),dayLabel=now.toLocaleDateString('zh-CN',{month:'long',day:'numeric'})+' · '+now.toLocaleDateString('zh-CN',{weekday:'long'});
    return `<header class="ws-page-head ws-team-home-head"><div><span class="today-workbench-eyebrow ws-home-date"><i></i><time>${esc(dayLabel)}</time></span><h1>让分散的讨论，成为共同的判断。</h1></div><div class="ws-actions">${btn('record',icon('mic')+'开始录音','primary')+'<button type="button" class="audio-upload-entry" data-audio-upload>'+icon('upload')+'上传</button>'+btn('agent',`<span class="ws-agent-mark">${icon('spark')}</span>Ask Agent`,'agent')}</div></header>`+
      (filter!=='trash'?teamIntelligence(report):'')+
      `<section class="ws-surface ws-recordings"><header class="ws-recording-head"><div><h2>${filter==='trash'?'录音回收站':'团队会议'}</h2><p>${filter==='trash'?'删除的录音可恢复，30 天后过期清理':'团队设备录音自动汇入，无需分享'}</p></div><div class="ws-meeting-tools"><label class="ws-search">${icon('search')}<input id="ws-file-search" type="search" placeholder="搜索会议" aria-label="搜索团队会议" value="${esc(query)}"></label><div class="ws-filter-source"><select id="ws-meeting-source" aria-label="会议来源">${['all','网页录音','合并录音','M1','W1','W2','W-PEN','文件上传','手动导入',...new Set(w().files.map(f=>f.source))].filter((x,i,a)=>a.indexOf(x)===i).map(v=>`<option value="${esc(v)}" ${sourceFilter===v?'selected':''}>${v==='all'?'全部来源':esc(v)}</option>`).join('')}</select></div><div class="ws-filter-date"><input id="ws-meeting-date" type="date" value="${dateFilter}" aria-label="录音日期"></div><select id="ws-meeting-status" aria-label="会议状态">${['all','已总结','处理中','待处理'].map(v=>`<option ${statusFilter===v?'selected':''} value="${v}">${v==='all'?'全部状态':v}</option>`).join('')}</select>${btn('recycle',filter==='trash'?'返回会议':icon('trash')+'录音回收站')}</div></header>${meetingTable()}</section>`;
  }
  function openMeeting(fid) {
    resetAgentOptions();draft='';answer='';
    if(dialog.open)dialog.close();
    M.getFile(w(),fid,actor);selected=fid;page='detail';agentOpen=false;activeHistoryId=null;activeInsightId=null;
    const wid=w().id,uid=actor;
    const space=()=>{if(data.activeId!==wid||actor!==uid)throw new Error('工作空间或成员已改变');return M.get(data,wid);};
    window.MeetingDetail.openWorkspace({id:wid,list:()=>M.visible(space(),uid),speakers:()=>space().members.filter(m=>m.status==='active').map(m=>m.name),canShare:id=>!M.teamRecording(space(),M.getFile(space(),id,uid)),editable:id=>space().status==='active'&&M.getFile(space(),id,uid).owner===uid,save:(id,r)=>mutate(()=>M.saveDetail(space(),id,r,uid)),share:id=>{selected=id;action('share',id).catch(e=>toast(e.message));},remove:id=>action('delete',id).catch(e=>toast(e.message)),close:()=>show('overview'),ask:(id,open)=>{selected=id;agentOpen=open;mountMeetingAgent();}},fid);
  }
  function mountMeetingAgent(){
    const detail=$('#meeting-detail-root'),host=$('#md-agent-host');if(!host)return;
    detail.classList.toggle('md-agent-open',agentOpen);host.hidden=!agentOpen;host.innerHTML=agentOpen?agent():'';
    const trigger=$('[data-md-action=ask]',detail);trigger?.setAttribute('aria-expanded',String(agentOpen));
    chrome();if(agentOpen)host.querySelector('textarea')?.focus({preventScroll:true});
  }
  function openContacts(){
    page='contacts';closeMenu();agentOpen=false;document.dispatchEvent(new Event('meeting-agent-leave'));
    const wid=w().id,uid=actor;const space=()=>{if(data.activeId!==wid||actor!==uid)throw new Error('工作空间或成员已改变');return M.get(data,wid);};
    window.ContactsUI.openWorkspace({id:wid,load:()=>M.clone({contacts:space().contacts,notes:space().contactNotes||{},tasks:space().contactTasks||[]}),check:()=>{if(!M.member(space(),uid))throw new Error('无成员访问权限');M.writable(space());},save:d=>{mutate(()=>M.saveContacts(space(),d,uid));chrome();},ask:(prompt,id)=>mutate(()=>M.askContact(space(),prompt,id,uid)),close:()=>show('overview')});chrome();
  }
  function files(){let list=M.visible(w(),actor);if(filter==='mine')list=list.filter(f=>f.owner===actor);if(filter==='shared')list=list.filter(f=>f.owner!==actor);if(filter==='trash')list=w().files.filter(f=>f.owner===actor&&f.deleted);list=list.filter(f=>f.title.toLowerCase().includes(query.toLowerCase()));return heading(w().type==='personal'?'个人空间文件':'团队会议录音','仅显示你创建或获邀访问的内容。管理员身份不会扩大文件访问范围。',btn('import',icon('upload')+'导入')+btn('record',icon('mic')+'开始录音','primary')+btn('agent',icon('spark')+'Ask Agent','agent'))+`<section class="ws-surface"><div class="ws-filter-bar"><nav class="ws-tabs" aria-label="文件筛选">${[['all','全部可见'],['mine','我的文件'],['shared','与我共享'],['trash','回收站']].map(([k,t])=>btn('filter',t,k===filter?'active':'',k)).join('')}</nav><label class="ws-search">${icon('search')}<input id="ws-file-search" placeholder="搜索文件" aria-label="搜索空间文件" value="${esc(query)}"></label></div>${filter==='trash'?`<div class="ws-list">${list.map(f=>`<div class="ws-list-row"><strong>${esc(f.title)}</strong>${btn('restore','恢复','',f.id)}</div>`).join('')||empty('回收站暂无内容','移入回收站的文件可以恢复。')}</div>`:list.length?fileTable(list):empty('这里还没有文件','通过录音或手动导入开始；其他空间的文件不会自动出现在这里。',btn('import','导入文件','primary'))}<div class="ws-table-foot">共 ${list.length} 份 · ${esc(w().name)}</div></section>`;}
  function detail(){const f=M.getFile(w(),selected,actor),owner=f.owner===actor;return heading(esc(f.title),`${esc(userName(f.owner))} · ${date(f.created)} · ${f.duration} 分钟 · ${f.shared.length?'已分享':'仅自己可见'}`,btn('page','返回文件','','files')+btn('export',icon('download')+'导出','',f.id)+(owner?btn('share',icon('share')+'分享','',f.id)+btn('delete',icon('trash')+'删除','danger',f.id):'')+btn('agent',icon('spark')+'Ask Agent','agent'))+`<section class="ws-surface ws-note"><nav class="ws-tabs" aria-label="文件内容">${[['summary','智能总结'],['transcript','转写文本']].map(([k,t])=>btn('file-tab',t,tab===k?'active':'',k)).join('')}</nav><div class="ws-note-toolbar"><span>内容由 AI 生成，仅供参考</span><div class="ws-actions">${owner?(editing?btn('exit-edit','退出编辑')+btn('save-edit','保存','primary'):btn('edit',icon('edit')+'编辑')):badge('伙伴分享 · 只读')}</div></div>${editing?`<textarea class="ws-editor" aria-label="编辑会议内容" id="ws-editor">${esc(noteDraft)}</textarea>`:`<article class="ws-prose">${esc(f[tab])}</article>`}<footer class="ws-note-footer">${icon('users')} ${f.shared.length?`已向 ${f.shared.map(userName).map(esc).join('、')} 分享`: '内容仅自己可见。可以邀请同一空间的成员查看。'}</footer></section>`;}
  function members(){const list=w().members.filter(m=>m.status!=='removed');return heading('成员与角色',`${M.usedSeats(w())} / ${w().seats} 席位已分配 · 待接受邀请也占用席位`,isAdmin()?btn('invite',icon('plus')+'邀请成员','primary'):'')+`<section class="ws-surface"><div class="ws-table-scroll"><table class="ws-table"><thead><tr><th>成员</th><th>角色</th><th>权益</th><th>状态</th><th>操作</th></tr></thead><tbody>${list.map(m=>`<tr><td><div class="ws-person"><span class="ws-mini-avatar">${esc(m.name[0])}</span><span><strong>${esc(m.name)} ${m.id===actor?'（我）':''}</strong><small>${esc(m.email)}</small></span></div></td><td>${m.role==='admin'?'管理员':'成员'}</td><td>${badge('Unlimited','blue')}</td><td>${badge(m.status==='pending'?'待接受':'已加入',m.status==='pending'?'amber':'green')}</td><td><div class="ws-actions">${isAdmin()?(m.status==='pending'?btn('member-resend','重发','link',m.id)+btn('member-accept','模拟接受','link',m.id):btn('member-role','调整角色','link',m.id))+(m.id!==actor?btn('member-remove',m.status==='pending'?'撤销':'移除','link danger',m.id):''): '—'}</div></td></tr>`).join('')}</tbody></table></div><div class="ws-table-foot">所有成员使用同一种席位权益。移除成员释放席位，不会自动减少账单。</div></section>${isAdmin()?`<div class="ws-info">${icon('users')} 管理员负责成员、设备和账单；团队设备录音自动对成员可见，私有记录仍按授权访问。</div>`:''}`;}
  function devices(){
    const all=data.devices.filter(d=>d.spaceId===w().id&&(isAdmin()||d.user===actor));
    return heading('设备与同步',w().type==='team'?'绑定团队设备的录音自动进入团队会议，成员无需额外分享即可查看。切换工作空间不会改变设备归属。':'录音同步到设备绑定的个人空间，仅自己可见。切换工作空间不会改变设备归属。',btn('bind',icon('plus')+'绑定已有设备','primary'))+`<section class="ws-surface"><div class="ws-table-scroll"><table class="ws-table"><thead><tr><th>设备</th><th>绑定成员</th><th>录音目标</th><th>最近同步</th><th>操作</th></tr></thead><tbody>${all.map(d=>`<tr><td><div class="ws-person"><span class="ws-device-mark">${icon('phone')}</span><span><strong>${esc(d.name)}</strong><small>SN ${esc(d.serial)} · ${esc(d.model)}</small></span></div></td><td>${esc(userName(d.user))}</td><td>${badge(w().name,'blue')}</td><td>${d.lastSync?date(d.lastSync):'尚未同步'}</td><td>${d.user===actor?btn('sync','模拟同步','link',d.id)+btn('device-detail','详情','link',d.id)+btn('unbind','解绑','link',d.id):btn('device-detail','查看','link',d.id)}</td></tr>`).join('')}</tbody></table></div>${!all.length?empty('当前空间尚未绑定设备',w().type==='personal'?'在手机 App 完成设备绑定后，即可在这里查看。':'可在 App 绑定设备，或录入设备信息并绑定团队成员。',w().type==='personal'?btn('bind','下载 App 绑定','primary'):''):''}</section>${w().type==='team'?`<section class="ws-surface"><div class="ws-section-head"><div><h2>设备录入</h2><p class="ws-muted">填写 SN 码和设备型号，绑定${isAdmin()?'对应的团队成员':'到自己'}。</p></div>${btn('register-device',icon('plus')+'录入设备')}</div></section>`:''}<div class="ws-info">${icon('phone')} 重新绑定只影响之后的录音。已有文件留在原空间，可手动导出、导入。</div>`;
  }
  function billing(){if(w().type==='personal')return personalBilling();
    if(!isAdmin())return heading('团队权益','你的权益由团队管理员统一管理。')+`<section class="ws-surface ws-perks"><h2>Team Unlimited</h2><p>你拥有独立的 Unlimited 转写权益，团队设备录音自动汇入团队会议。</p>${badge(w().status==='active'?'权益生效中':'当前只读',w().status==='active'?'green':'amber')}<p>账单、席位和续费请联系团队管理员。</p>${btn('leave','退出当前空间','danger')}</section>`;
    const space=w();return heading('订阅与席位','团队统一付款，每位成员独立获得完整的 Unlimited 权益。')+managementTabs()+seatOrderNotice()+`<div class="ws-billing-grid"><section class="ws-surface ws-plan-current"><div class="ws-section-head"><h2>Team Unlimited</h2>${badge(space.status==='active'?(space.renew?'订阅生效中':'已取消自动续费'):'已到期 · 只读',space.status==='active'?'green':'amber')}</div><div class="ws-plan-amount">${money(M.price(space.cycle)*space.seats)}<small>/ ${space.cycle==='year'?'年':'月'}</small></div><p>${space.seats} 席位 × ${money(M.price(space.cycle))} / ${space.cycle==='year'?'年':'月'} · 演示价格</p><div class="ws-plan-divider"></div><div class="ws-seat-usage"><strong>${M.usedSeats(space)} <small>/ ${space.seats} 已分配</small></strong><span>${space.seats-M.usedSeats(space)} 个可用席位</span></div><progress max="${space.seats}" value="${M.usedSeats(space)}"></progress><div class="ws-actions">${btn('seats','管理席位','primary')}${btn('cycle','切换'+(space.cycle==='year'?'月付':'年付'))}</div>${space.pendingCycle?`<div class="ws-info">下周期改为 ${space.pendingCycle==='year'?'年付':'月付'} ${btn('cancel-cycle','撤销','link')}</div>`:''}${space.pendingSeats?`<div class="ws-info">下周期调整为 ${space.pendingSeats} 席位 ${btn('cancel-reduction','撤销','link')}</div>`:''}<p class="ws-muted">${space.renew?'下次续费':'权益保留至'}：${space.nextDate}</p></section><section class="ws-surface ws-billing-details"><h3>账单信息</h3><dl><dt>公司名称</dt><dd>${esc(space.billing.company)}</dd><dt>账单邮箱</dt><dd>${esc(space.billing.email)}</dd><dt>支付方式</dt><dd>${esc(space.billing.method)}</dd></dl>${btn('billing-info','编辑账单信息')}<div class="ws-plan-divider"></div><div class="ws-actions">${btn('renew',space.status!=='active'?'恢复订阅':space.renew?'取消自动续费':'恢复自动续费','link')}${btn('advance-cycle','模拟下一账期','link')}${btn('expire','模拟到期','link danger')}</div><small>支付与订单均为本地演示，不会真实扣款。</small></section></div><section class="ws-surface"><div class="ws-section-head"><h2>账单历史</h2></div><div class="ws-table-scroll"><table class="ws-table"><thead><tr><th>账单</th><th>项目</th><th>金额</th><th>状态</th><th>凭证</th></tr></thead><tbody>${space.invoices.map(i=>`<tr><td>${esc(i.id)}<small>${date(i.date)}</small></td><td>${esc(i.label)}</td><td>${money(i.amount)}</td><td>${badge(i.status,'green')}</td><td>${btn('invoice','下载','link',i.id)}</td></tr>`).join('')}</tbody></table></div></section>`;}
  const PS=window.PersonalSubscriptionModel;
  let personalCycle='year';
  const dollars=v=>'$'+Number(v).toFixed(2);
  function personalBilling(){
    const sub=PS.current(w()),orders=w().personalOrders||[],pending=orders.find(o=>['pending','failed'].includes(o.status));
    return heading('个人订阅','个人空间的转写、摘要与 Agent 权益。')+`<section class="ws-surface ps-account"><div><span class="ws-mini-avatar">张</span><div><h2>张伟 <span class="ws-badge ${sub.plan==='Pro'?'blue':'amber'}">${sub.plan}</span></h2><p>${sub.plan==='Pro'?`${sub.renew?'下次续费':'权益保留至'}：${date(sub.endsAt)} · ${sub.cycle==='year'?'连续包年':'连续包月'}`:'标准版 · 每月 400 分钟'}</p></div></div><div><strong>${sub.minutes.toLocaleString()} <small>/ ${sub.minutes.toLocaleString()} 分钟剩余</small></strong><progress max="${sub.minutes}" value="${sub.minutes}"></progress><small>${sub.nextRefresh?'下次分钟 / Credits 刷新：'+date(sub.nextRefresh):'个人订阅与团队席位分别计费'}</small></div>${sub.plan==='Pro'?btn('personal-renew',sub.renew?'取消自动续费':'恢复自动续费','link'):''}</section>${pending?`<div class="ws-seat-pending"><div><strong>个人订阅支付未完成</strong><span>Pro · ${pending.cycle==='year'?'连续包年':'连续包月'} · ${dollars(pending.amount)}</span></div>${btn('personal-checkout','继续支付','',pending.id)}</div>`:''}<section class="ws-surface ps-plans"><div class="ps-plan-head"><span>✦ Pro</span><p>在转写与摘要之外，解锁高级 AI 分析。</p></div><div class="ps-plan-options">${Object.values(PS.plans).map(p=>`<button type="button" class="ps-plan-option ${personalCycle===p.cycle?'selected':''}" data-ws-action="personal-cycle" data-value="${p.cycle}" aria-pressed="${personalCycle===p.cycle}">${p.cycle==='year'?'<span class="ps-saving">每年节省 $115.89</span>':''}<h3>${p.cycle==='year'?'连续包年':'连续包月'}</h3><strong>${dollars(p.amount)} <small>/ ${p.cycle==='year'?'年':'月'}</small></strong><dl><dt>每月 Credits</dt><dd>5,000 Credits</dd><dt>每月转写与摘要分钟数</dt><dd>99,999 分钟</dd></dl></button>`).join('')}</div><div class="ps-plan-details"><h3>订阅详情</h3><p>每月 5,000 Credits，用于 Agent 分析；每月 99,999 分钟转写与摘要时长。年付套餐按年支付，权益按月刷新。</p><p>支付为本地模拟，不会真实扣款。标准版每月包含 400 分钟。</p></div><div class="ps-plan-footer">${btn('personal-buy',sub.plan==='Pro'&&sub.cycle===personalCycle?'当前套餐':sub.plan==='Pro'?'切换 Pro 套餐':'立即升级 Pro','primary','',sub.plan==='Pro'&&sub.cycle===personalCycle?'disabled':'')}${btn('personal-restore','恢复购买','link')}</div></section><section class="ws-surface"><div class="ws-section-head"><h2>个人订阅订单</h2></div><div class="ws-table-scroll"><table class="ws-table"><thead><tr><th>订单</th><th>套餐</th><th>金额</th><th>状态</th><th>操作</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${esc(o.id)}<small>${date(o.created)}</small></td><td>Pro · ${o.cycle==='year'?'年付':'月付'}</td><td>${dollars(o.amount)}</td><td>${badge({pending:'待支付',failed:'支付失败',paid:'已支付',cancelled:'已取消'}[o.status])}</td><td>${o.status==='paid'?btn('personal-receipt','下载账单','link',o.id):o.status==='cancelled'?'—':btn('personal-checkout','继续支付','link',o.id)+btn('personal-cancel','取消','link',o.id)}</td></tr>`).join('')||'<tr><td colspan="5">暂无个人订阅订单</td></tr>'}</tbody></table></div></section>`;
  }
  function personalCheckout(orderId){const o=PS.get(w(),orderId);if(o.status==='paid')return personalSuccess(o);if(o.status==='cancelled')throw new Error('订单已取消');modal('确认个人订阅',`<div class="ws-steps"><span>1 选择套餐</span><b>2 确认并支付</b><span>3 权益生效</span></div><div class="ws-order"><h3>Pro · ${o.cycle==='year'?'连续包年':'连续包月'}</h3><p>订单 ${esc(o.id)}</p><div><span>账户</span><strong>${esc(data.account.email)}</strong></div><div><span>每月权益</span><strong>5,000 Credits · 99,999 分钟</strong></div><div><span>本次应付</span><strong>${dollars(o.amount)} USD</strong></div></div>${select('模拟支付方式','method',[['Visa ···· 4242','Visa ···· 4242'],['Apple Pay（模拟）','Apple Pay（模拟）']],'Visa ···· 4242')}<p class="ws-muted">支付成功后立即生效，随后每${o.cycle==='year'?'年':'月'}按 ${dollars(o.amount)} 自动续费，可随时取消续费并保留已购期间权益。年付的分钟数与 Credits 仍按月刷新。</p><p class="ws-info">本地模拟，不会扣款。切换套餐演示按新套餐全额计费、从支付日起重新起算，不折抵旧套餐；正式差价规则待确认。</p>${o.status==='failed'?'<p class="ws-seat-payment-error" role="alert">模拟支付失败，未扣款、未开通权益。可重试或取消。</p>':''}<input type="hidden" name="orderId" value="${esc(o.id)}"><input type="hidden" name="workspaceId" value="${esc(w().id)}">`,btn('personal-cancel','取消订单','',o.id)+btn('personal-fail','模拟支付失败','link',o.id)+submit('模拟支付 '+dollars(o.amount)),'personal-pay');}
  function personalSuccess(o){modal('Pro 已生效',`<div class="ws-success"><span class="ws-credit-success-mark">✓</span><h3>模拟支付成功</h3><strong>Pro · ${o.cycle==='year'?'连续包年':'连续包月'}</strong><p>每月 5,000 Credits · 99,999 分钟</p><p>权益至 ${date(o.subscription.endsAt)}</p></div><p class="ws-muted">本次 ${dollars(o.amount)} USD；未发生真实扣款。个人权益已更新，团队订阅不受影响。</p>`,btn('personal-receipt','下载账单','',o.id)+btn('close-dialog','完成','primary'));}
  function personalFresh(){if(w().type!=='personal')throw new Error('请返回个人空间');if(localStorage.getItem(M.KEY)!==savedState)throw new Error('订阅数据已在其他页面更新，请刷新后重试');}
  function seatOrderNotice(){
    const order=(w().seatOrders||[]).find(o=>['pending','failed'].includes(o.status));
    return order?`<div class="ws-seat-pending" role="status"><div><strong>${order.status==='failed'?'加席支付未完成':'有一笔待支付的加席订单'}</strong><span>增加 ${order.added} 席位 · ${money(order.amount)} · 当前席位尚未变更</span></div><div class="ws-actions">${btn('seat-checkout','继续支付','',order.id)}${btn('seat-cancel','取消订单','link',order.id)}</div></div>`:'';
  }
  function manageSeats(count=w().pendingSeats??w().seats){
    M.govern(w(),actor);M.writable(w());
    modal('管理席位',`${field('调整后的总席位数','seats',count,'number',`required min="${Math.max(2,M.usedSeats(w()))}" max="50" step="1"`)}<p>当前已购 ${w().seats} 席位，已分配 ${M.usedSeats(w())} 席位（含待接受邀请）。</p><div id="ws-seat-estimate" class="ws-seat-estimate" aria-live="polite"></div><p class="ws-muted">新增席位支付成功后生效；减少席位在下一账期生效。</p>`,btn('close-dialog','取消')+submit('下一步'),'seats');updateSeatEstimate();
  }
  function updateSeatEstimate(){
    const input=$('[data-ws-form=seats] [name=seats]',dialog),estimate=$('#ws-seat-estimate');if(!input||!estimate)return;
    const count=Number(input.value),button=$('[data-ws-form=seats] [type=submit]',dialog);
    if(!input.validity.valid||!input.value){estimate.textContent='请输入有效的席位数量';button.textContent='下一步';return;}
    if(count>w().seats){estimate.innerHTML=`<span>新增 ${count-w().seats} 席位 · ${w().cycle==='year'?'年付':'月付'}</span><strong>${money((count-w().seats)*M.price(w().cycle))}</strong><small>本次应付 · 演示按完整周期计价</small>`;button.textContent='下一步：确认费用';}
    else {estimate.textContent=count<w().seats?`将于 ${w().nextDate} 调整为 ${count} 席位，本次无需支付。`:w().pendingSeats?'将取消已安排的减席，保持当前席位，本次无需支付。':'席位数量未变化，本次无需支付。';button.textContent=count<w().seats?'确认下期调整':'确认';}
  }
  function seatCheckout(orderId){
    const order=M.getSeatOrder(w(),orderId,actor);if(order.status==='paid')return seatPaymentSuccess(order);if(order.status==='cancelled')throw new Error('订单已取消，请重新选择席位');
    modal('确认加席订单',`<div class="ws-steps"><span>1 选择席位</span><b>2 确认并支付</b><span>3 生效</span></div><div class="ws-order ws-seat-order"><h3>${esc(w().name)}</h3><p>订单 ${esc(order.id)}</p><div><span>总席位</span><strong>${order.fromSeats} → ${order.targetSeats} 席位</strong></div><div><span>新增席位</span><strong>${order.added} × ${money(order.unitPrice)} / ${order.cycle==='year'?'年':'月'}</strong></div><div class="ws-seat-total"><span>本次应付</span><strong>${money(order.amount)}</strong></div></div><p class="ws-muted">演示按新增席位的完整${order.cycle==='year'?'年度':'月度'}价格计费，不按剩余天数折算；现有账期不变。正式计费规则待确认。</p>${order.snapshot!==JSON.stringify([w().id,w().seats,w().cycle,w().nextDate,w().pendingSeats??null,w().pendingCycle??null,w().renew,w().status])?'<p class="ws-seat-payment-error">席位或订阅已变化，请返回修改并重新确认费用。</p>':''}${w().pendingSeats?'<p class="ws-info">支付成功后，将取消已安排的减席计划。</p>':''}<div class="ws-seat-payment-method"><span>模拟支付方式</span><strong>${esc(w().billing.method)}</strong></div><p class="ws-muted">${w().renew?'下次续费':'当前权益截止'}：${esc(order.nextDate)}${w().renew?` · ${order.targetSeats} 席位 · ${money(order.nextAmount)} / ${order.nextCycle==='year'?'年':'月'}`:'（自动续费已关闭）'}</p>${order.status==='failed'?'<div class="ws-seat-payment-error" role="alert">模拟支付失败，未扣款、未增加席位。可以重试或取消订单。</div>':''}<input type="hidden" name="orderId" value="${esc(order.id)}"><input type="hidden" name="workspaceId" value="${esc(w().id)}"><div class="ws-info">本地模拟支付，不会真实扣款。关闭窗口后可在账单页继续支付。</div>`,btn('seat-back','返回修改','',order.id)+btn('seat-cancel','取消订单','',order.id)+btn('seat-pay-fail','模拟支付失败','link',order.id)+submit(`${order.status==='failed'?'重试模拟支付':'模拟支付'} ${money(order.amount)}`),'seat-pay');
  }
  function seatPaymentSuccess(order){
    modal('席位已增加',`<div class="ws-steps"><span>1 选择席位</span><span>2 确认并支付</span><b>3 已生效</b></div><div class="ws-success"><h3>模拟支付成功</h3><p>新增 ${order.added} 席位已生效，总席位 ${order.targetSeats} 个。</p><strong>${money(order.amount)}</strong><p>账单 ${esc(order.invoiceId)}</p></div><p class="ws-muted">已更新可用席位与账单记录，可继续邀请成员。未发生真实扣款。</p>`,btn('close-dialog','完成','primary'));
  }
  function creditPackPicker(packId=M.CREDIT_PACKS[0].id){
    M.govern(w(),actor);M.writable(w());
    modal('购买 Credits',`<div class="ws-steps"><b>1 选择套餐</b><span>2 确认并支付</span><span>3 到账</span></div><p>购买后进入「${esc(w().name)}」的共享池，供所有成员的 Agent 使用。</p><div class="ws-credit-packs">${M.CREDIT_PACKS.map(p=>`<label><input type="radio" name="packId" value="${p.id}" ${p.id===packId?'checked':''} required><span><strong>${creditNumber(p.credits)} Credits</strong><small>一次性购买 · 团队共享</small></span><b>${money(p.amount)}</b></label>`).join('')}</div><input type="hidden" name="workspaceId" value="${esc(w().id)}"><p class="ws-muted">演示价格，不会真实扣款。购买 Credits 不改变席位数、个人空间余额或转写权益。</p>`,btn('close-dialog','取消')+submit('下一步：确认订单'),'credit-pack');
  }
  function creditCheckout(orderId){
    const order=M.getCreditOrder(w(),orderId,actor);if(order.status==='paid')return creditPaymentSuccess(order);if(order.status==='cancelled')throw new Error('订单已取消，请重新购买');
    modal('确认 Credits 订单',`<div class="ws-steps"><span>1 选择套餐</span><b>2 确认并支付</b><span>3 到账</span></div><div class="ws-order"><h3>${esc(w().name)}</h3><p>订单 ${esc(order.id)}</p><div><span>购买数量</span><strong>${creditNumber(order.credits)} Credits</strong></div><div><span>到账位置</span><strong>当前团队共享池</strong></div><div><span>本次应付</span><strong>${money(order.amount)}</strong></div></div><div class="ws-seat-payment-method"><span>模拟支付方式</span><strong>${esc(w().billing.method)}</strong></div><p class="ws-muted">一次性购买，无自动续购。支付成功后 Credits 才会到账，并生成独立账单。</p>${order.status==='failed'?'<div class="ws-seat-payment-error" role="alert">模拟支付失败，未扣款、未增加 Credits。可重试或取消订单。</div>':''}<input type="hidden" name="workspaceId" value="${esc(w().id)}"><input type="hidden" name="orderId" value="${esc(order.id)}"><div class="ws-info">本地模拟支付，不会真实扣款。关闭窗口后，可从 Credits 页继续支付。</div>`,btn('credit-back','返回修改','',order.id)+btn('credit-cancel','取消订单','',order.id)+btn('credit-pay-fail','模拟支付失败','link',order.id)+submit(`${order.status==='failed'?'重试模拟支付':'模拟支付'} ${money(order.amount)}`),'credit-pay');
  }
  function creditPaymentSuccess(order){
    modal('Credits 已到账',`<div class="ws-steps"><span>1 选择套餐</span><span>2 确认并支付</span><b>3 已到账</b></div><div class="ws-success"><span class="ws-credit-success-mark">✓</span><h3>模拟支付成功</h3><strong>+${creditNumber(order.credits)} Credits</strong><p>已加入「${esc(w().name)}」共享池</p><p>当前可用 ${creditNumber(M.creditBalance(w()))} Credits</p></div><div class="ws-order"><p>订单 ${esc(order.id)}</p><p>实付 ${money(order.amount)} · 账单 ${esc(order.invoiceId)}</p></div><p class="ws-muted">未发生真实扣款。重复查看此结果不会重复到账。</p>`,btn('invoice','下载账单','',order.invoiceId)+btn('close-dialog','完成','primary'));
  }
  function creditOrderActions(order){
    if(order.status==='paid')return btn('credit-checkout','查看结果','link',order.id)+btn('invoice','下载账单','link',order.invoiceId);
    if(order.status==='cancelled')return '<span class="ws-muted">已关闭</span>';
    return btn('credit-checkout',order.status==='failed'?'重试支付':'继续支付','link',order.id)+btn('credit-cancel','取消','link danger',order.id);
  }
  function credits(){
    M.govern(w(),actor);const c=w().credits,orders=w().creditOrders||[],pending=orders.find(o=>['pending','failed'].includes(o.status));
    return heading('团队 Credits','所有成员共用一个 Credits 池。Agent 按输入与输出 token 用量扣减，独立于席位的转写权益。',btn('topup','购买 Credits','primary'))+managementTabs()+
      `${pending?`<div class="ws-seat-pending"><div><strong>${pending.status==='failed'?'Credits 支付未完成':'有一笔待支付的 Credits 订单'}</strong><span>${creditNumber(pending.credits)} Credits · ${money(pending.amount)}</span></div><div class="ws-actions">${creditOrderActions(pending)}</div></div>`:''}<section class="ws-surface ws-credit-summary"><div><span>可用 Credits</span><strong>${creditNumber(M.creditBalance(w()))}</strong></div><div><span>累计消耗 Credits</span><strong>${creditNumber(c.used)}</strong></div></section><section class="ws-surface"><div class="ws-section-head"><div><h2>使用记录</h2><p class="ws-muted">Token 用量为本地模拟；正式接入后按模型返回的实际用量结算。</p></div></div><div class="ws-table-scroll"><table class="ws-table ws-credit-usage"><thead><tr><th>任务</th><th>成员</th><th>消耗 Credits</th><th>时间</th></tr></thead><tbody>${c.logs.map(l=>`<tr><td>${esc(l.task)}<small>${l.inputTokens!=null?'Token 用量模拟':'历史记录 · 未记录 Token 明细'}</small></td><td>${esc(userName(l.user))}</td><td>−${creditNumber(l.amount)}</td><td>${date(l.time)}</td></tr>`).join('')||'<tr><td colspan="4">暂无使用记录</td></tr>'}</tbody></table></div></section><section class="ws-surface"><div class="ws-section-head"><h2>购买记录</h2></div><div class="ws-table-scroll"><table class="ws-table ws-credit-orders"><thead><tr><th>订单</th><th>Credits</th><th>金额</th><th>状态</th><th>操作</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${esc(o.id)}<small>${date(o.created)}</small></td><td>${creditNumber(o.credits)}</td><td>${money(o.amount)}</td><td>${badge({pending:'待支付',failed:'支付失败',paid:'已到账',cancelled:'已取消'}[o.status],o.status==='paid'?'green':'')}</td><td><div class="ws-actions">${creditOrderActions(o)}</div></td></tr>`).join('')||'<tr><td colspan="5">暂无 Credits 购买记录</td></tr>'}</tbody></table></div></section>`;
  }

  function settings(){M.govern(w(),actor);return heading('空间设置','名称、成员权限与隐私设置仅作用于当前工作空间。')+managementTabs()+`<form class="ws-surface ws-settings-form" data-ws-form="settings">${field('工作空间名称','name',w().name,'text','required maxlength="40"')}${field('公司所在地区','country',w().country,'text','disabled')}<p class="ws-muted">地区在创建时确定，后续保持不变。</p><div class="ws-info">${icon('users')} 团队设备录音自动进入团队会议，当前空间成员可查看；个人空间的数据保持隔离。</div><p class="ws-form-error" role="alert"></p><button class="ws-btn primary" type="submit">保存设置</button></form><section class="ws-surface ws-settings-form"><h3>退出工作空间</h3><p>退出后将无法访问此空间。若你是唯一管理员，需要先指定另一位管理员。</p>${btn('leave','退出当前空间','danger')}</section>`;}
  function audit(){M.govern(w(),actor);return heading('活动记录','只记录空间管理操作，不向管理员暴露成员私有文件内容。')+managementTabs()+`<section class="ws-surface"><div class="ws-list">${w().audit.filter(l=>!l.action.match(/文件|私有/)).map(l=>`<div class="ws-list-row"><div><strong>${esc(l.action)}</strong><small>${esc(l.actor)}</small></div><time>${date(l.time)}</time></div>`).join('')||empty('暂无管理活动','创建、邀请、席位与设备变更会显示在这里。')}</div></section>`;}
  function contacts(){return heading('团队联系人','当前工作空间的合作关系与跟进记录。',btn('contact-add','添加联系人','primary'))+`<div class="ws-contact-grid">${(w().contacts||[]).map(c=>`<button class="ws-contact-card" data-ws-action="contact" data-value="${esc(c.id)}"><span class="ws-mini-avatar">${esc(c.name[0])}</span><h3>${esc(c.name)}</h3><small>${esc(c.company)} · ${esc(c.role)}</small><p>${esc(c.summary)}</p><span class="ws-link">查看与跟进 ↗</span></button>`).join('')||empty('暂时没有联系人','添加合作伙伴，建立当前团队独立的关系记录。')}</div>`;}
  function agent(){const thread=activeHistoryId?M.history(w(),actor).find(t=>t.id===activeHistoryId):null;const insight=activeInsightId?M.insights(w(),actor).items.find(i=>i.id===activeInsightId):null;return `<aside class="ws-agent" aria-label="Ask Agent"><header><div><span class="ws-agent-mark">${icon('spark')}</span><div><h2>Ask Agent</h2><p>${esc(w().name)}</p></div></div>${btn('agent-close',icon('x'),'ws-icon-button','','aria-label="收起 Agent"')}</header><div class="ws-agent-scroll"><span class="ws-eyebrow">仅引用当前空间已授权的内容</span>${thread?`<div class="ws-agent-history-context"><span class="ws-eyebrow">历史会话</span><h3>${esc(thread.title||thread.prompt)}</h3><p><time>${date(thread.time)}</time></p></div>`:insight?`<div class="ws-agent-insight-context"><span>正在讨论</span><h3>${esc(insight.title)}</h3><p>${esc(insight.description)}</p><div class="ws-agent-insight-sources">${insight.sources.map(e=>btn('file',icon('mic')+esc(e.title),'link',e.fileId)).join('')}</div></div>`:`<h3>${selected?'继续这场会议的工作':'让团队讨论有下一步'}</h3><p>整理关键结论、拆解行动项，或准备下一次沟通。</p><div class="ws-agent-prompts">${['整理待推进的行动项','为下次会议准备简报'].map(t=>btn('prompt',t,'',t)).join('')}</div>`}${(thread?M.conversation(w(),thread.id,actor):M.history(w(),actor).filter(t=>!t.demo&&t.user===actor&&(!insight||t.prompt.includes(insight.title))&&(!selected||(t.files||[]).includes(selected))).slice(0,4).reverse()).map(t=>`<div class="ws-chat-user">${esc(t.prompt)}</div><div class="ws-chat-answer">${esc(t.answer)}</div>${t.usage?`<div class="ws-agent-usage">输入 ${creditNumber(t.usage.inputTokens)} / 输出 ${creditNumber(t.usage.outputTokens)} tokens · ${creditNumber(t.usage.cost)} Credits（模拟）</div>`:''}`).join('')}${answer?`<div class="ws-chat-answer" role="status">${esc(answer)}</div>`:''}</div><form class="ws-composer" data-ws-form="ask"><textarea name="question" aria-label="向团队 Agent 提问" aria-describedby="ws-composer-hint" placeholder="输入问题，按 Enter 发送…">${esc(draft)}</textarea><div class="ws-composer-tools">${btn('agent-sources',icon('book'),'ws-tool'+(agentOptions.fileIds.length||selected||thread?' selected':''),'','aria-label="引用资料" title="引用资料"')}${btn('agent-web',icon('globe'),'ws-tool'+(agentOptions.web?' selected':''),'',`aria-label="联网搜索" aria-pressed="${agentOptions.web}" title="联网搜索（模拟）"`)}<label class="ws-agent-mode">${icon('clock')}<select name="mode" aria-label="回答模式"><option value="quick" ${agentOptions.mode==='quick'?'selected':''}>快速</option><option value="deep" ${agentOptions.mode==='deep'?'selected':''}>深度思考</option></select></label><button class="ws-btn primary" type="submit" aria-label="发送问题" ${draft.trim()?'':'disabled'}>${icon('send')}</button></div><small id="ws-composer-hint">${agentOptions.fileIds.length?'已引用 '+agentOptions.fileIds.length+' 场会议':thread?'已引用当前历史会话':selected?'已引用当前会议':'基于当前工作空间'}${agentOptions.appData?' · 应用数据':''}${agentOptions.web?' · 联网模拟':''}</small><div class="ws-composer-caption"><small>Enter 发送 / Shift+Enter 换行</small><small>按 Token 用量结算 · 本地模拟</small></div><p class="ws-form-error" role="alert"></p></form></aside>`;}
  function refreshAgent(){if(page==='detail')mountMeetingAgent();else render();}
  function taskEditor(t=null){
    modal(t?'自动任务':'新建自动任务',`<input type="hidden" name="id" value="${esc(t?.id||'')}">${field('任务名称','title',t?.title||'','text','required maxlength="80"')}<label class="ws-field">任务要求<textarea name="prompt" required maxlength="2000">${esc(t?.prompt||'')}</textarea></label><div class="ws-two-fields">${select('重复频率','frequency',[['daily','每天'],['weekly','每周五']],t?.frequency||'weekly')}${field('执行时间（GMT+8）','time',t?.time||'09:00','time','required')}</div><p class="ws-muted">仅本人可见。基于当前团队可访问的会议；本地模拟不在后台定时执行，可点击“模拟运行”预览结果，按实际输入与输出 Token 用量模拟扣减 Credits。</p>${t?`<p class="ws-muted">状态：${t.enabled?'已启用':'已暂停'} · 最近运行：${esc(t.lastRun||'尚未运行')}</p><div class="ws-actions">${btn('auto-toggle',t.enabled?'暂停任务':'启用任务','',t.id)}${btn('auto-run','模拟运行','',t.id,t.enabled?'':'disabled')}</div>${(t.runs||[]).slice(0,3).map(r=>`<p>${esc(r.time)} ${M.history(w(),actor).some(h=>h.id===r.threadId)?btn('history','查看结果','link',r.threadId):'<span class="ws-muted">会话已删除或不可访问</span>'}</p>`).join('')}`:''}`,btn('close-dialog','取消')+submit('保存任务'),'auto-task');
  }
  function render(){
    if(w().type==='personal')refreshPersonal();
    let body;try{body=({overview,files,detail,members,devices,billing,credits,settings,audit,contacts}[page]||overview)();}catch(e){body=empty('此页面暂不可访问',esc(e.message),btn('page','返回团队首页','primary','overview'));}
    root.innerHTML=`${w().type==='team'&&w().status!=='active'?`<div class="ws-readonly">当前空间已到期，文件可继续查看与导出。${isAdmin()?btn('page','恢复订阅 →','link','billing'):''}</div>`:''}<div class="ws-layout${agentOpen?' with-agent':''}"><div class="ws-content">${body}<footer class="ws-demo-footer">交互演示 · 数据保存在本浏览器${w().type==='team'?`<label>体验成员视角 <select id="ws-actor" aria-label="体验成员视角">${w().members.filter(m=>m.status==='active').map(m=>`<option value="${m.id}" ${actor===m.id?'selected':''}>${esc(m.name)} · ${m.role==='admin'?'管理员':'成员'}</option>`).join('')}</select></label>`:''}</footer></div>${agentOpen?agent():''}</div>`;
    chrome();window.MeetingFilters?.enhance('ws-meeting-source','source');window.MeetingFilters?.enhance('ws-meeting-date','date');requestAnimationFrame(fit);
  }
  function modal(title,body,footer='',form='') {if(dialog.open)dialog.close();dialog.innerHTML=`<div class="ws-dialog-head"><h2>${title}</h2>${btn('close-dialog',icon('x'),'ws-icon-button','','aria-label="关闭"')}</div><${form?'form':'div'} ${form?`data-ws-form="${form}"`:''} class="ws-dialog-content">${body}<p class="ws-form-error" role="alert"></p>${footer?`<footer class="ws-dialog-footer">${footer}</footer>`:''}</${form?'form':'div'}>`;dialog.showModal();}
  function confirm(title,copy,fn){modal(title,`<p>${copy}</p>`,btn('close-dialog','取消')+btn('confirm','确认','primary'));confirm.fn=fn;}
  const submit=label=>`<button class="ws-btn primary" type="submit">${label}</button>`;
  function plan(){setup={step:0,name:'',country:'中国',cycle:'year',seats:3,orderId:M.id('order')};renderPlan();}
  function renderPlan(){modal('EurekaMind Team',`<div class="ws-plan-intro"><div><span class="ws-eyebrow">一个账号，无缝协作</span><h1>让团队的每次讨论<br>都有下一步。</h1><p>从独立记录到授权协作，在一个清晰可控的工作空间完成。</p><ul><li>${icon('folder')}<div><strong>独立的团队会议录音</strong><span>团队设备录音自动归集，成员共同查看</span></div></li><li>${icon('users')}<div><strong>成员与席位统一管理</strong><span>每个席位都享有完整 Unlimited 权益</span></div></li><li>${icon('phone')}<div><strong>设备绑定到空间</strong><span>录音同步位置清晰，切换时不混淆</span></div></li><li>${icon('spark')}<div><strong>团队 Credits 共享池</strong><span>按 Token 用量使用，独立于转写权益</span></div></li></ul></div><section class="ws-pricing"><span class="ws-eyebrow">TEAM UNLIMITED</span><div class="ws-cycle">${btn('plan-cycle','月付',setup.cycle==='month'?'active':'','month')}${btn('plan-cycle','年付',setup.cycle==='year'?'active':'','year')}</div><div class="ws-price">${money(setup.cycle==='year'?159:199)}<small>/ 席位 / 月</small></div><p>${setup.cycle==='year'?'按年结算，每席位 ¥1,908 / 年':'按月结算，灵活调整席位'}</p>${btn('setup','创建团队','primary')}<ul><li>✓ 每席位独立 Unlimited 转写</li><li>✓ 50,000 团队 Credits</li><li>✓ 成员、设备与账单管理</li><li>✓ 2–50 席位，可随时扩容</li></ul><small>本版本演示定价，不会发起真实支付。</small></section></div>`);dialog.classList.add('ws-dialog-wide');}
  function renderSetup(){dialog.classList.remove('ws-dialog-wide');modal('创建团队工作空间',`<div class="ws-steps"><b>1 空间信息</b><span>2 确认订单</span><span>3 开通</span></div>${field('工作空间名称','name',setup.name,'text','required maxlength="40" placeholder="例如：EurekaMind 产品团队"')}${select('公司所在地区','country',[['中国','中国'],['新加坡','新加坡'],['美国','美国'],['其他','其他']],setup.country)}<div class="ws-two-fields">${field('席位数量','seats',setup.seats,'number','required min="2" max="50" step="1"')}${select('计费周期','cycle',[['year','年付 · ¥159 / 席位 / 月'],['month','月付 · ¥199 / 席位 / 月']],setup.cycle)}</div><p class="ws-muted">至少 2 席位。你作为管理员占用 1 席位。个人订阅与文件保持独立。</p>`,btn('close-dialog','取消')+submit('确认订单'),'setup');}
  function checkout(){modal('确认团队订单',`<div class="ws-steps"><span>1 空间信息</span><b>2 确认订单</b><span>3 开通</span></div><div class="ws-order"><h3>${esc(setup.name)}</h3><p>${esc(setup.country)} · Team Unlimited · ${setup.cycle==='year'?'年付':'月付'}</p><div><span>${setup.seats} 席位 × ${money(M.price(setup.cycle))}</span><strong>${money(setup.seats*M.price(setup.cycle))}</strong></div><div><span>本次模拟支付</span><strong>${money(setup.seats*M.price(setup.cycle))}</strong></div></div><div class="ws-info">演示订单：无需银行卡，不会真实扣款或发送邮件。</div>`,btn('setup','上一步')+btn('payment-fail','模拟支付失败')+btn('payment','模拟支付并开通','primary'));}
  function inviteDialog(){M.govern(w(),actor);M.writable(w());modal('邀请空间成员',`<p>邀请加入 <strong>${esc(w().name)}</strong></p><p>当前可邀请 <b>${Math.min(w().seats,w().pendingSeats??w().seats)-M.usedSeats(w())}</b> 位伙伴。邀请发送后即占用席位。</p><label class="ws-field">邮箱地址<textarea name="emails" required placeholder="name@company.com，多位用逗号分隔"></textarea></label>${select('角色','role',[['member','成员 · 使用录音与 AI，管理自己的文件'],['admin','管理员 · 管理成员、设备和账单']],'member')}<p class="ws-muted">本地模拟邀请，不会发送真实邮件。</p>`,btn('page','增加席位','','billing')+submit('发送模拟邀请'),'invite');}
  const download=(name,text,type='application/json')=>{const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([text],{type}));link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);};
  function registerDeviceDialog(){
    M.writable(w());
    const members=w().members.filter(m=>m.status==='active'&&(isAdmin()||m.id===actor));
    deviceRegistration={workspaceId:w().id,actor};
    modal('录入并绑定设备',`<p>录入设备信息，并选择使用这台设备的成员。</p>${field('SN 码','serial','','text','required maxlength="64" placeholder="例如：474204126010000027" autocomplete="off" spellcheck="false"')}${field('设备型号','model','','text','required maxlength="40" placeholder="例如：W2"')}${select('绑定成员','user',members.map(m=>[m.id,`${m.name} · ${m.email}${m.id===actor?'（我）':''}`]),actor)}<div class="ws-record-target">录音目标：<strong>${esc(w().name)}</strong></div><p class="ws-muted">保存后设备将显示在列表中；新录音记录绑定成员，并自动进入团队会议供空间成员查看。</p>`,btn('close-dialog','取消')+submit('保存并绑定'),'register-device');
  }
  function binding(){
    modal('绑定你的设备',`<div class="ws-device-guide"><section class="ws-device-guide-card"><h3>已经有设备？</h3><p>在手机上下载 EurekaMind App，<br>登录后即可绑定你的设备。</p><div class="ws-device-guide-art ws-device-guide-qr"><img src="assets/download/eurekamind-download-qr.png" alt="扫码下载 EurekaMind App" width="240" height="240"></div><a class="ws-btn ws-device-download" href="https://eurekamind.ai/download" target="_blank" rel="noopener noreferrer">${icon('phone')}下载 App ${icon('expand')}</a><small>iOS / Android · 手机扫码下载</small></section><section class="ws-device-guide-card"><h3>还没有设备？</h3><p>了解 EurekaMind 录音设备，<br>让每一次对话都成为有价值的记录。</p><div class="ws-device-guide-art"><img src="assets/download/eurekamind-device.webp" alt="EurekaMind 录音设备" width="280" height="280"></div><a class="ws-btn primary" href="https://eurekamind.ai/shop" target="_blank" rel="noopener noreferrer">购买设备 ${icon('expand')}</a><small>前往 EurekaMind 官方商城</small></section></div><p class="ws-device-guide-note">在 App 中登录同一账号，选择「${esc(w().name)}」完成设备绑定。绑定成功后，录音将同步到设备所属的工作空间。</p>`);
  }

  async function action(name,value,button){
    if(name==='personal-cycle'){personalCycle=value;render();return;}
    if(name==='personal-buy'){personalFresh();const o=mutate(()=>PS.create(w(),personalCycle));render();return personalCheckout(o.id);}
    if(name==='personal-checkout')return personalCheckout(value);
    if(name==='personal-cancel'){PS.get(w(),value);confirm('取消个人订阅订单？','未支付的订单取消后不会扣款或开通权益。',()=>{personalFresh();mutate(()=>PS.cancel(w(),value));render();});return;}
    if(name==='personal-fail'){personalFresh();const method=$('[name=method]',dialog).value;mutate(()=>PS.pay(w(),value,'failure',method));render();return personalCheckout(value);}
    if(name==='personal-renew'){const sub=PS.current(w());confirm(sub.renew?'取消自动续费？':'恢复自动续费？',sub.renew?'当前已购权益将保留至到期，不再自动续费。':'到期按当前套餐价格续费（本地模拟）。',()=>{personalFresh();mutate(()=>PS.renew(w(),!sub.renew));render();});return;}
    if(name==='personal-restore'){personalFresh();mutate(()=>PS.restore(w()));render();toast('已恢复本浏览器的有效个人订阅，没有再次扣款或发放 Credits');return;}
    if(name==='personal-receipt'){const o=PS.get(w(),value);if(o.status!=='paid')throw new Error('订单尚未支付');const blob=new Blob([`EurekaMind 个人订阅账单（本地模拟）\n订单：${o.id}\n账单：${o.invoiceId}\nPro ${o.cycle==='year'?'年付':'月付'}\n金额：${dollars(o.amount)} USD\n支付时间：${o.paidAt}\n未发生真实扣款。`],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=o.invoiceId+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
    if(name==='menu')return openMenu(button);
    if(name==='switch')return switchSpace(value);
    if(name==='page'){if(dialog.open)dialog.close();return show(value);}
    if(name==='close-dialog'){dialog.classList.remove('ws-dialog-wide');return dialog.close();}
    if(name==='confirm'){dialog.close();confirm.fn?.();return;}
    if(name==='plan'){closeMenu();return plan();}
    if(name==='plan-cycle'){setup.cycle=value;return renderPlan();}
    if(name==='setup'){dialog.classList.remove('ws-dialog-wide');return renderSetup();}
    if(name==='payment-fail'){$('.ws-form-error',dialog).textContent='模拟支付失败，未创建空间或扣款。请重试。';return;}
    if(name==='payment'){mutate(()=>M.create(data,setup));actor=M.SELF;chrome();show('overview');modal('团队已准备好',`<div class="ws-success">${icon('users')}<h3>${esc(w().name)}</h3><p>${w().seats} 个席位已开通。可以邀请伙伴，也可以直接进入团队开始工作。</p></div>`,btn('close-dialog','进入团队')+btn('invite','邀请伙伴','primary'));return;}
    if(name==='invites'){closeMenu();modal('工作空间邀请',data.invitations.filter(i=>i.status==='pending').map(i=>`<div class="ws-invitation"><h3>${esc(i.teamName)}</h3><p>${esc(i.admin)} 邀请你以成员身份加入，团队为你提供 Unlimited 席位。</p>${btn('decline-invite','婉拒','',i.id)}${btn('join','接受并进入','primary',i.id)}</div>`).join('')||empty('没有待处理的邀请','新的工作空间邀请会显示在这里。'));return;}
    if(name==='join'){mutate(()=>M.acceptInvite(data,value));dialog.close();switchSpace(data.activeId);return;}
    if(name==='decline-invite'){mutate(()=>{const i=data.invitations.find(i=>i.id===value);if(i)i.status='declined';});return action('invites');}
    if(name==='logout'){closeMenu();confirm('退出登录？','工作空间数据会保留在当前浏览器，重新登录后可继续体验。',()=>location.replace(new URL('../auth-shell.html',location.href).href));return;}
    if(name==='settings'){closeMenu();if(w().type==='personal'){window.openUserSettings?.();const email=$('.settings-profile strong');if(email)email.textContent=data.account.email;const plan=$('.settings-profile small');if(plan)plan.textContent='Pro · 个人工作空间';return;}return show(isAdmin()?'settings':'billing');}
    if(name==='recycle'){filter=filter==='trash'?'all':'trash';listPage=1;query='';return show('overview');}
    if(name==='sort'){sortAsc=sortKey===value?!sortAsc:false;sortKey=value;return render();}
    if(name==='list-prev'||name==='list-next'){listPage+=name==='list-prev'?-1:1;return render();}
    if(name==='meeting-prompt'){resetAgentOptions();if(dialog.open)dialog.close();selected=null;activeHistoryId=null;activeInsightId=M.insights(w(),actor).items.find(i=>i.title===value)?.id||null;agentOpen=true;draft=value;answer='';render();$('.ws-composer textarea')?.focus({preventScroll:true});return;}
    if(name==='purge'){confirm('永久删除录音？','永久删除后无法恢复，其他成员的访问也将失效。',()=>{mutate(()=>M.purge(w(),value,actor));render();});return;}
    if(name==='filter'){filter=value;return render();}
    if(name==='file'&&w().type==='team')return openMeeting(value);
    if(name==='file'){const original=M.getFile(w(),value,actor);if(original.nativeId){root.hidden=true;window.MeetingDetail.open(original.title);return;}selected=value;tab='summary';editing=false;return show('detail');}
    if(name==='file-tab'){if(editing){toast('请先保存或退出编辑');return;}tab=value;return render();}
    if(name==='edit'){noteDraft=M.getFile(w(),selected,actor)[tab];editing=true;return render();}
    if(name==='exit-edit'){confirm('退出编辑？','未保存的内容会丢失。',()=>{editing=false;render();});return;}
    if(name==='save-edit'){mutate(()=>M.edit(w(),selected,{[tab]:$('#ws-editor').value},actor));editing=false;render();toast('内容已保存');return;}
    if(name==='export'){if(w().type==='personal')refreshPersonal();download(M.getFile(w(),value,actor).title+'.json',JSON.stringify(M.exportFile(w(),value,actor),null,2));return;}
    if(name==='import'){modal('手动导入文件',`<p>将导出的 EurekaMind JSON 文件导入 <b>${esc(w().name)}</b>。新副本默认仅自己可见，原文件保持不变。</p><label class="ws-field">选择文件<input name="file" type="file" accept=".json,application/json" required></label>`,btn('close-dialog','取消')+submit('导入当前空间'),'import');return;}
    if(name==='share'){const f=M.getFile(w(),value,actor);if(M.teamRecording(w(),f)){toast('团队设备录音已向团队成员开放，无需分享');return;}modal('分享给空间成员',`<p>${esc(f.title)}</p><p class="ws-muted">勾选成员可访问此文件，取消勾选将撤销访问。不会向其他空间开放。</p><div class="ws-share-list">${w().members.filter(m=>m.status==='active'&&m.id!==actor).map(m=>`<label><input type="checkbox" name="users" value="${m.id}" ${f.shared.includes(m.id)?'checked':''}><span>${esc(m.name)}<small>${esc(m.email)}</small></span>${badge('可查看')}</label>`).join('')||'<p>当前空间没有其他成员。</p>'}</div><input type="hidden" name="fileId" value="${value}">`,btn('close-dialog','取消')+submit('保存访问权限'),'share');return;}
    if(name==='delete'){confirm('移入回收站？','此录音将从列表中移除，伙伴的访问权限也会暂时失效。30 天内可在录音回收站恢复。',()=>{mutate(()=>M.trash(w(),value,false,actor));selected=null;show('files');});return;}
    if(name==='restore'){mutate(()=>M.trash(w(),value,true,actor));render();toast('文件已恢复');return;}
    if(name==='record'){M.writable(w());modal('新建网页录音',`${field('会议名称','title','','text','required placeholder="例如：十月产品评审"')}<div class="ws-record-target">${icon('mic')} 保存到 <b>${esc(w().name)}</b> · 仅自己可见</div><p class="ws-muted">进入录音界面，可暂停、继续、标记重点和结束保存。本地模拟，不启用麦克风。</p>`,btn('close-dialog','取消')+submit('开始模拟录音'),'record');return;}
    if(name==='invite'){closeMenu();return inviteDialog();}
    if(name==='member-resend'||name==='member-accept'){mutate(()=>M.memberAction(data,w(),value,name==='member-resend'?'resend':'accept',null,actor));render();toast(name==='member-resend'?'模拟邀请已重发':'成员已模拟接受邀请');return;}
    if(name==='member-role'){M.govern(w(),actor);const m=w().members.find(m=>m.id===value);modal('调整成员角色',`<p>${esc(m.name)} · ${esc(m.email)}</p><input type="hidden" name="memberId" value="${value}">${select('角色','role',[['member','成员'],['admin','管理员']],m.role)}<p class="ws-muted">管理员可以管理账单、成员和设备，但不能访问其他人的私有文件。</p>`,btn('close-dialog','取消')+submit('保存角色'),'role');return;}
    if(name==='member-remove'){confirm('移除此成员？','将撤销此成员的空间访问权限并释放席位，设备绑定会解除。订阅的席位数量和账单不会自动减少。',()=>{mutate(()=>M.memberAction(data,w(),value,'remove',null,actor));render();toast('成员已移除，席位已释放');});return;}
    if(name==='seats')return manageSeats();
    if(name==='seat-checkout')return seatCheckout(value);
    if(name==='seat-back'){const order=M.getSeatOrder(w(),value,actor);return manageSeats(order.targetSeats);}
    if(name==='seat-cancel'){if(localStorage.getItem(M.KEY)!==savedState)throw new Error('空间数据已在其他页面更新，请刷新后重新确认订单');mutate(()=>M.cancelSeatOrder(w(),value,actor));dialog.close();render();toast('订单已取消，席位未变更');return;}
    if(name==='seat-pay-fail'){
      if(localStorage.getItem(M.KEY)!==savedState)throw new Error('空间数据已在其他页面更新，请刷新后重新确认订单');
      mutate(()=>M.paySeatOrder(w(),value,'failure',actor));render();return seatCheckout(value);
    }
    if(name==='cancel-reduction'){mutate(()=>{M.govern(w(),actor);w().pendingSeats=null;M.log(w(),'取消下周期减席',actor);});render();return;}
    if(name==='cycle'){confirm('切换计费周期？',`改为${w().cycle==='year'?'月付':'年付'}后，下一周期费用为 ${money((w().pendingSeats??w().seats)*M.price(w().cycle==='year'?'month':'year'))}。本次为演示，不产生真实扣款。`,()=>{mutate(()=>{M.govern(w(),actor);M.writable(w());w().pendingCycle=w().cycle==='year'?'month':'year';M.log(w(),'安排下周期切换计费方式',actor);});render();});return;}
    if(name==='cancel-cycle'){mutate(()=>{M.govern(w(),actor);w().pendingCycle=null;});render();return;}
    if(name==='advance-cycle'){confirm('模拟下一账期？','将应用已安排的席位与计费周期变更，生成模拟续费账单。已取消续费的空间将进入只读。',()=>{mutate(()=>M.advanceCycle(w(),actor));render();});return;}
    if(name==='billing-info'){M.govern(w(),actor);modal('账单信息',`${field('公司名称','company',w().billing.company,'text','required')}${field('账单邮箱','email',w().billing.email,'email','required')}${field('税号（可选）','taxId',w().billing.taxId)}${select('模拟支付方式','method',[['Visa ···· 4242','Visa ···· 4242'],['Mastercard ···· 5555','Mastercard ···· 5555']],w().billing.method)}`,btn('close-dialog','取消')+submit('保存'),'billing');return;}
    if(name==='renew'){confirm(w().renew&&w().status==='active'?'取消自动续费？':'恢复订阅？',w().renew&&w().status==='active'?`当前权益保留至 ${w().nextDate}，到期后进入只读模式。`:'恢复后可以继续录音、转写和 Agent 分析。本次为本地模拟。',()=>{mutate(()=>{M.govern(w(),actor);w().renew=!(w().renew&&w().status==='active');w().status='active';M.log(w(),'更新自动续费设置',actor);});render();});return;}
    if(name==='expire'){confirm('模拟订阅到期？','用于体验只读状态，文件仍可查看与导出；可随时在此恢复订阅。',()=>{mutate(()=>{M.govern(w(),actor);w().status='expired';M.log(w(),'模拟订阅到期',actor);});render();});return;}
    if(name==='invoice'){M.govern(w(),actor);const i=w().invoices.find(i=>i.id===value);download(i.id+'.txt',`EurekaMind 模拟账单\n${i.id}\n${w().billing.company}\n${i.label}\n${money(i.amount)}\n${date(i.date)}\n仅供演示，不作为真实支付或报销凭证。`,'text/plain');return;}
    if(name==='topup')return creditPackPicker();
    if(name==='credit-checkout')return creditCheckout(value);
    if(name==='credit-back'){if(localStorage.getItem(M.KEY)!==savedState)throw new Error('空间数据已更新，请刷新后重试');const order=M.getCreditOrder(w(),value,actor);mutate(()=>M.cancelCreditOrder(w(),value,actor));render();return creditPackPicker(order.packId);}
    if(name==='credit-cancel'){M.getCreditOrder(w(),value,actor);confirm('取消 Credits 订单？','取消后不会扣款或增加 Credits。',()=>{if(localStorage.getItem(M.KEY)!==savedState)throw new Error('空间数据已更新，请刷新后重试');mutate(()=>M.cancelCreditOrder(w(),value,actor));render();toast('订单已取消');});return;}
    if(name==='credit-pay-fail'){if(localStorage.getItem(M.KEY)!==savedState)throw new Error('空间数据已更新，请刷新后重试');mutate(()=>M.payCreditOrder(w(),value,'failure',actor));render();return creditCheckout(value);}

    if(name==='bind')return binding();
    if(name==='register-device')return registerDeviceDialog();
    if(name==='unbind'){confirm('模拟解除设备绑定？','解除后设备不再向此空间同步，已有录音保留。可在 App 重新绑定。',()=>{mutate(()=>{const d=data.devices.find(d=>d.id===value);if(!d||d.user!==actor)throw new Error('只能解绑自己的设备');M.writable(w());d.spaceId=null;M.log(w(),'模拟解绑自己的设备',actor);});render();});return;}

    if(name==='sync'){const result=mutate(()=>M.sync(data,value,actor));render();toast(`已同步至${result.space.name}，${M.teamRecording(result.space,result.file)?'团队成员可直接查看':'新录音仅自己可见'}`);return;}
    if(name==='device-detail'){const d=data.devices.find(d=>d.id===value);modal(esc(d.name),`<dl class="ws-device-detail"><dt>序列号</dt><dd>${esc(d.serial)}</dd><dt>设备型号</dt><dd>${esc(d.model)}</dd><dt>绑定空间</dt><dd>${esc(M.get(data,d.spaceId).name)}</dd><dt>绑定成员</dt><dd>${esc(userName(d.user))}</dd><dt>同步说明</dt><dd>切换界面不会改变设备的录音同步位置。管理员仅可查看设备元数据。</dd></dl>`,btn('close-dialog','关闭'));return;}
    if(name==='history-tab'){historyTab=value;chrome();return;}
    if(name==='history-delete'){
      const spaceId=w().id,uid=actor;
      confirm('删除会话？','此会话及其续聊记录将一并删除，原始会议录音不受影响。',()=>{if(w().id!==spaceId||actor!==uid)throw new Error('空间或成员已改变，请重试');const removed=mutate(()=>M.deleteConversation(w(),value,actor));if(removed.includes(activeHistoryId)){activeHistoryId=null;answer='';draft='';agentOpen=false;}refreshAgent();toast('会话已删除');});return;
    }
    if(name==='auto-new'){taskEditor();return;}
    if(name==='auto-task'){taskEditor(M.getTask(w(),value,actor));return;}
    if(name==='auto-delete'){M.getTask(w(),value,actor);confirm('删除自动任务？','停止该自动任务，已生成的历史会话仍保留。',()=>{mutate(()=>{M.getTask(w(),value,actor);w().automaticTasks=w().automaticTasks.filter(t=>t.id!==value);});chrome();toast('自动任务已删除');});return;}
    if(name==='auto-toggle'){mutate(()=>{M.writable(w());const t=M.getTask(w(),value,actor);t.enabled=!t.enabled;});chrome();taskEditor(M.getTask(w(),value,actor));return;}
    if(name==='auto-run'){const result=mutate(()=>M.runTask(w(),value,actor));if(!result.threadId){toast(result.answer);return;}dialog.close();historyTab='all';return action('history',result.threadId);}
    if(name==='agent-web'){agentOptions.web=!agentOptions.web;refreshAgent();return;}
    if(name==='agent-sources'){
      const context=agentOptions.fileIds.length?agentOptions.fileIds:activeHistoryId?M.getThread(w(),activeHistoryId,actor).files:selected?[selected]:[];
      modal('引用资料',`<p class="ws-muted">仅展示当前空间有权访问的音频文件。未选择时沿用当前会话或页面上下文。</p><div class="ws-source-options">${M.visible(w(),actor).map(f=>`<label><input type="checkbox" name="files" value="${esc(f.id)}" ${context.includes(f.id)?'checked':''}>${icon('mic')}<span>${esc(f.title)}</span></label>`).join('')}</div><label class="ws-source-app"><input type="checkbox" name="appData" ${agentOptions.appData?'checked':''}>应用数据（所选会议的名称与处理状态）</label><p class="ws-muted">不会引用个人闪念、联系人或其他空间资料。</p>`,btn('close-dialog','取消')+submit('确认引用'),'agent-sources');return;
    }
    if(name==='history'){const t=M.getThread(w(),value,actor);if(dialog.open)dialog.close();resetAgentOptions();agentOptions.mode=t.mode||'quick';agentOptions.web=!!t.web;agentOptions.appData=!!t.appData;activeInsightId=null;show('overview');activeHistoryId=value;agentOpen=true;draft='';answer='';render();$('.ws-composer textarea')?.focus({preventScroll:true});return;}
    if(name==='agent'){resetAgentOptions();activeInsightId=null;activeHistoryId=null;agentOpen=true;answer='';return render();}
    if(name==='agent-close'){agentOpen=false;return page==='detail'?mountMeetingAgent():render();}
    if(name==='prompt'){draft=value;if(page==='detail')mountMeetingAgent();else render();$('.ws-composer textarea')?.focus({preventScroll:true});return;}
    if(name==='leave'){if(actor!==M.SELF)throw new Error('请先切回自己的视角，再退出工作空间');confirm('退出工作空间？','退出后你将无法访问此空间的文件。个人空间不受影响。',()=>{mutate(()=>{const m=M.member(w(),M.SELF);if(m.role==='admin'&&w().members.filter(x=>x.status==='active'&&x.role==='admin').length===1)throw new Error('请先指定另一位管理员');m.status='removed';data.devices.filter(d=>d.spaceId===w().id&&d.user===M.SELF).forEach(d=>d.spaceId=null);});switchSpace('personal');});return;}
    if(name==='contact-add'){modal('添加团队联系人',field('姓名','name','','text','required')+field('公司','company')+field('角色','role')+field('跟进事项','summary'),btn('close-dialog','取消')+submit('添加'),'contact');return;}
    if(name==='contact'){const c=w().contacts.find(c=>c.id===value);modal(esc(c.name),`<p>${esc(c.company)} · ${esc(c.role)}</p><p>${esc(c.summary)}</p><label class="ws-field">更新跟进事项<textarea name="summary">${esc(c.summary)}</textarea></label><input type="hidden" name="id" value="${c.id}">`,btn('close-dialog','关闭')+submit('保存跟进'),'contact-update');return;}
  }
  async function formAction(form){const values=new FormData(form),v=Object.fromEntries(values);const kind=form.dataset.wsForm;
    if(kind==='personal-pay'){personalFresh();if(v.workspaceId!==w().id)throw new Error('工作空间已变化');const o=mutate(()=>PS.pay(w(),v.orderId,'success',v.method));render();return personalSuccess(o);}
    if(kind==='auto-task'){mutate(()=>M.saveTask(w(),v,actor));dialog.close();chrome();toast('自动任务已保存');return;}
    if(kind==='agent-sources'){const ids=values.getAll('files');ids.forEach(id=>M.getFile(w(),id,actor));agentOptions.fileIds=ids;agentOptions.appData=values.has('appData');dialog.close();refreshAgent();return;}
    if(kind==='setup'){setup={...setup,...v,seats:Number(v.seats)};return checkout();}
    if(kind==='invite'){mutate(()=>M.invite(w(),v.emails,v.role,actor));dialog.close();show('members');toast('模拟邀请已创建，可在成员列表体验接受流程');return;}
    if(kind==='role')mutate(()=>M.memberAction(data,w(),v.memberId,'role',v.role,actor));
    if(kind==='seats'){
      if(localStorage.getItem(M.KEY)!==savedState)throw new Error('空间数据已在其他页面更新，请刷新后重新确认席位');
      if(Number(v.seats)>w().seats){const order=mutate(()=>M.createSeatOrder(w(),v.seats,actor));render();return seatCheckout(order.id);}
      mutate(()=>M.seats(w(),v.seats,actor));
    }
    if(kind==='seat-pay'){
      if(v.workspaceId!==w().id)throw new Error('工作空间已变化，请回到原空间完成订单');
      if(localStorage.getItem(M.KEY)!==savedState)throw new Error('空间数据已在其他页面更新，请刷新后重新确认订单');
      const order=mutate(()=>M.paySeatOrder(w(),v.orderId,'success',actor));render();return seatPaymentSuccess(order);
    }
    if(kind==='share')mutate(()=>M.share(w(),v.fileId,values.getAll('users'),actor));
    if(kind==='record'){M.writable(w());recordingContext={spaceId:w().id,actor,title:v.title};dialog.close();window.RecordingUI.start();$('#recording-name').textContent=v.title;return;}
    if(kind==='import'){const file=values.get('file');if(file.size>2*1024*1024)throw new Error('请选择小于 2 MB 的纪要 JSON');let content;try{content=JSON.parse(await file.text());}catch{throw new Error('文件不是有效 JSON');}const f=mutate(()=>M.importFile(w(),content,actor));selected=f.id;dialog.close();if(w().type==='team')openMeeting(f.id);else show('detail');toast('已创建独立副本，仅自己可见');return;}
    if(kind==='billing')mutate(()=>{M.govern(w(),actor);w().billing=v;M.log(w(),'更新账单信息',actor);});
    if(kind==='settings')mutate(()=>{M.govern(w(),actor);M.writable(w());const name=v.name.trim();if(!name)throw new Error('名称不能为空');w().name=name;M.log(w(),'更新空间名称',actor);});
    if(kind==='credit-pack'||kind==='credit-pay'){
      if(v.workspaceId!==w().id)throw new Error('工作空间已变化，请重新确认订单');
      if(localStorage.getItem(M.KEY)!==savedState)throw new Error('空间数据已在其他页面更新，请刷新后继续支付');
      if(kind==='credit-pack'){const order=mutate(()=>M.createCreditOrder(w(),v.packId,actor));render();return creditCheckout(order.id);}
      const order=mutate(()=>M.payCreditOrder(w(),v.orderId,'success',actor));render();return creditPaymentSuccess(order);
    }

    if(kind==='register-device'){
      if(!deviceRegistration||deviceRegistration.workspaceId!==w().id||deviceRegistration.actor!==actor)throw new Error('工作空间或操作身份已改变，请关闭后重新录入');
      if(localStorage.getItem(M.KEY)!==savedState)throw new Error('工作空间数据已更新，请先备份当前输入，刷新页面后重新录入');
      const device=mutate(()=>M.registerDevice(data,deviceRegistration.workspaceId,v,deviceRegistration.actor));
      dialog.close();render();toast(`设备 ${device.model} 已录入并绑定至 ${userName(device.user)}`);return;
    }
    if(kind==='ask'){const context=activeInsightId?M.insights(w(),actor).items.find(i=>i.id===activeInsightId):null;const question=context&&String(v.question).trim()&&!v.question.includes(context.title)?context.title+'：'+v.question:v.question;const result=mutate(()=>M.ask(w(),question,selected,actor,activeHistoryId,agentOptions));draft='';answer=result.cost?'':result.answer;activeHistoryId=result.threadId||activeHistoryId;agentOptions.fileIds=[];if(page==='detail')mountMeetingAgent();else render();requestAnimationFrame(()=>{const messages=$('.ws-agent-scroll');if(messages)messages.scrollTop=messages.scrollHeight;});return;}
    if(kind==='contact')mutate(()=>{M.writable(w());(w().contacts||=[]).push({id:M.id('contact'),...v});});
    if(kind==='contact-update')mutate(()=>{M.writable(w());w().contacts.find(c=>c.id===v.id).summary=v.summary;});
    dialog.close();if(page==='detail'&&w().type==='team')openMeeting(selected);else render();toast('已保存');
  }
  document.addEventListener('click',e=>{const b=e.target.closest('[data-ws-action]');if(!b){if(!menu.hidden&&!menu.contains(e.target))closeMenu();return;}e.preventDefault();action(b.dataset.wsAction,b.dataset.value,b).catch(err=>{const error=dialog.open?$('.ws-form-error',dialog):null;if(error)error.textContent=err.message;else toast(err.message);});});
  document.addEventListener('submit',e=>{const form=e.target.closest('[data-ws-form]');if(!form)return;e.preventDefault();const submitButton=form.querySelector('[type=submit]');if(submitButton?.disabled)return;if(submitButton)submitButton.disabled=true;formAction(form).catch(err=>{$('.ws-form-error',form).textContent=err.message;}).finally(()=>{if(submitButton)submitButton.disabled=false;});});
  document.addEventListener('input',e=>{if(e.target.matches('[data-ws-form=seats] [name=seats]'))updateSeatEstimate();if(e.target.id==='ws-file-search'){query=e.target.value;listPage=1;const pos=e.target.selectionStart;render();const input=$('#ws-file-search');input.focus({preventScroll:true});input.setSelectionRange(pos,pos);}if(e.target.matches('.ws-composer textarea')){draft=e.target.value;e.target.form.querySelector('[type=submit]').disabled=!draft.trim();}if(e.target.id==='ws-editor')noteDraft=e.target.value;});
  document.addEventListener('change',e=>{if(e.target.matches('.ws-composer [name=mode]'))agentOptions.mode=e.target.value;});
  root.addEventListener('change',e=>{if(e.target.id==='ws-meeting-source'||e.target.id==='ws-meeting-date'||e.target.id==='ws-meeting-status'){if(e.target.id==='ws-meeting-source')sourceFilter=e.target.value;else if(e.target.id==='ws-meeting-date')dateFilter=e.target.value;else statusFilter=e.target.value;listPage=1;render();return;}if(e.target.id==='ws-actor'){activeHistoryId=null;activeInsightId=null;actor=e.target.value;historyTab='all';resetAgentOptions();selected=null;editing=false;answer='';draft='';agentOpen=false;show('overview');toast('已切换演示视角，内容按此成员的权限展示');}});
  document.addEventListener('keydown',e=>{if(e.target.matches('.ws-composer textarea')&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();e.target.form.requestSubmit();}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
  window.addEventListener('click',e=>{
    const footer=e.target.closest('#user-card');if(footer){e.preventDefault();e.stopImmediatePropagation();openMenu(footer);return;}
    if(w().type!=='team')return;
    if(e.target.closest('[data-personal-view=thoughts],#thoughts-entry')){e.preventDefault();e.stopImmediatePropagation();return;}
    const home=e.target.closest('#home-entry'),record=e.target.closest('#start-recording'),contact=e.target.closest('[data-contacts-entry]');
    if(e.target.closest('#recording-finish')&&recordingContext&&!recordingContext.savedId){
      try {const c=recordingContext,space=M.get(data,c.spaceId);const f=mutate(()=>M.addFile(space,{title:$('#recording-name').textContent||c.title,duration:Math.max(1,Math.ceil(window.RecordingUI.seconds()/60)),transcript:$('#transcript-stream').innerText},c.actor));c.savedId=f.id;}
      catch(err){e.preventDefault();e.stopImmediatePropagation();toast(err.message);return;}
    }
    const recordingBack=e.target.closest('#recording-back-home,#recording-abandon');
    if(recordingBack&&recordingContext){if(recordingBack.id==='recording-back-home'&&!window.RecordingUI.ended())return;e.preventDefault();e.stopImmediatePropagation();window.RecordingUI.stop();recordingContext=null;show('overview');return;}
    if(home||record||contact){e.preventDefault();e.stopImmediatePropagation();if(recordingContext&&!window.RecordingUI.ended()){confirm('放弃当前演示录音？','当前录音尚未保存，离开后将停止录音。',()=>{window.RecordingUI.stop();recordingContext=null;if(home)show('overview');else if(contact)show('contacts');else action('record').catch(err=>toast(err.message));});return;}if(home)show('overview');else if(contact)show('contacts');else action('record').catch(err=>toast(err.message));}
  },true);
  dialog.addEventListener('close',()=>dialog.classList.remove('ws-dialog-wide'));
  window.addEventListener('resize',()=>{fit();closeMenu();});new ResizeObserver(fit).observe($('.topbar'));
  window.EurekaSpaces={id:()=>data.activeId,open:show,switch:switchSpace,
    uploadContext(){M.writable(w());if(!M.member(w(),actor))throw Error('当前成员无法上传');return {id:w().id,type:w().type,name:w().name,actor};},
    uploadAudio(meta,context){
      if(context.id!==w().id||context.actor!==actor)throw Error('工作空间已改变，请重新打开上传');
      const f=mutate(()=>{const f=M.addFile(w(),{title:meta.title,source:'文件上传',summary:meta.note,transcript:meta.note},actor);Object.assign(f,{origin:'upload',fileName:meta.name,size:meta.size,status:'待处理',visibility:'team',recordedWorkspaceId:w().id});if(w().audit[0])w().audit[0].action='上传团队录音：'+f.title;return f;});
      filter='all';query='';sourceFilter='all';dateFilter='';statusFilter='all';listPage=1;show('overview');return f;
    }
  };
  if(!data.spaces.some(s=>s.id===data.activeId&&M.member(s)))data.activeId='personal';chrome();if(w().type==='team')show('overview');
})();
